// Biztonsági kapu: az AI csak egy fájlnevet és tartalmat kérhet; a videómappát a fő workflow adja át.
// A Read/Write Files node engedélye a teljes /data/videos gyökérre szól, ezért itt elutasítjuk
// az abszolút útvonalakat, almappákat és útvonalbejárást, mielőtt a fájlíró node lefutna.
const input = $input.first().json;
const videoFolder = String(input.videoFolder ?? '');
const fileName = String(input.fileName ?? '');
const content = input.content;
const userMessage = String(input.userMessage ?? '').trim().toLocaleLowerCase('hu-HU');
if (fileName === 'meta.json' && userMessage !== 'kész' && userMessage !== 'kesz') {
  throw new Error('A meta.json csak külön, új jóváhagyó üzenet után írható. Az MD-fázisban kizárólag meta.md menthető; várd meg, hogy a user az MD átnézése után pontosan azt írja: Kész.');
}
if (!/^[A-Za-z0-9][A-Za-z0-9 _.-]{0,119}$/.test(videoFolder) || videoFolder === '.' || videoFolder === '..' || videoFolder.includes('..')) {
  throw new Error('A kiválasztott videómappa neve érvénytelen.');
}
if (!/^[A-Za-z0-9][A-Za-z0-9._-]{0,119}$/.test(fileName) || fileName.includes('..')) {
  throw new Error('Érvénytelen fájlútvonal: csak egyszerű fájlnév engedélyezett a kiválasztott videómappán belül; almappa és külső útvonal nem írható.');
}
if (typeof content !== 'string') throw new Error('A fájl tartalmának szövegnek kell lennie.');
const targetPath = `/data/videos/${videoFolder}/${fileName}`;
return [{ json: { videoFolder, fileName, content, targetPath } }];
